// The gallery's block texts in English (spec 2026-10-23 languages-b §9): display name, description and notes of every id HANDLES points at.
// Block ids, parameter names, cut.ts code and English technical terms stay as they are. blocks.test.ts checks every id has one.
import type { BlockText } from './blocks.ts';

export const BLOCKS_EN: Record<string, BlockText> = {
  'core.flash': { label: 'Flash', doc: 'Flashes a color over the whole frame (white by default); retakes, transitions, a camera shutter; keys \"second:opacity\" follows keyframes (fade to black, fade from white, a double flash); mode bloom is a glow spreading from one point (x, y), growing until it fills the frame (the light at the end of a tunnel, memories, endings); blend changes the blend mode (screen only brightens).' },
  'core.title': { label: 'Title', doc: 'A big title in the middle of the frame, with an optional subtitle line; openers and chapter starts.' },
  'core.caption': { label: 'Caption', doc: 'One line of caption at the bottom of the frame (can wrap, can have a background); speech captions, narration, explanations.' },
  'core.lowerThird': { label: 'Lower third', doc: 'A main line plus subtitle with a color bar at the lower left; places, names, times.' },
  'core.endCard': { label: 'End card', doc: 'Several lines of text appearing one by one at the end (one entry per line); thanks, credits, dates.' },
  'common.backdrop': { label: 'Backdrop pattern', doc: 'A patterned background for the whole film (plaid, dots, stripes, grid, solid, gradient), placed under the video; it is the ground that shows when the video shrinks into a panel, with colors taken from the theme. glow lets a patch of light show through at the bottom, its strength following "seconds:strength" (getting hotter with the score or the mood); diamond is the diamond pattern of a cash-register mat, pool adds a ring of warm light and vignette darkens the corners (dark counters, workbenches); spot is a dark poster ground: a soft light falls from the top edge (color2, density tint) and it fades darker below (quotes, interviews, podcasts).' },
  'common.ambient': { label: 'Shifting ambient background', doc: 'The background color of the whole film shifts along a series of colors with a "level" (deeper the further you dive, darker as it gets later, bluer as it gets colder), with drifting particles and fading light beams; placed under the video, and its value is shared with common.meter. look sky is the sky of a day: the level is the mood (0 dawn, 1 storm, 2 clearing, 3 golden hour, 4 dusk, 5 night) with drifting clouds, thin rain in the storm, sun as it clears, string-light glow at dusk, stars at night, and lightning at the flash times (the weather of a birthday, a wedding, a day in a vlog; thunder: common.thunder).' },
  'common.shader': { label: 'Animated background (GPU)', doc: 'A flowing textured background for the whole film, drawn live on the GPU: mesh flowing gradient, grain grainy gradient, rays light beams, smoke smoke rings, warp warped grid, swirl vortex, blobs fluid balls, dots dot orbits; colors default to the theme; placed under the video (openers, end cards, sections without footage, behind panels).' },
  'common.panel': { label: 'Video panel frame', doc: 'A thick frame around a video shrunk into a rectangle (rounded corners, hard shadow, taped on at an angle). look: print turns it into a white photo-paper border with a soft shadow and two strips of washi tape on top (planners, recipes); bezel is a narrow dark frame with a very deep soft shadow (a screen set into a machine or sign); hole fills everything outside the frame with a dark ground (faint light, fine diagonal lines) and draws a ring-colored line around the frame edge (signboard layouts, queue displays); offset has no frame: a shifted block of color (block, offset to the lower right by shadow) behind the video window slides out from behind it at the start, like a misprinted plate (quote posters, interviews); drawn is a hand-drawn frame: pen picks crayon / marker / pencil / ballpoint, it is drawn stroke by stroke within drawIn seconds at the start, the line wobbles boil times per second, with a thin ring-colored line outside (double) and tape stickers at the corners (picture books, notebooks, doodle style). x, y, w, h must equal the video\'s frame and radius must equal the video\'s corner radius; place it above the video track.' },
  'common.badge': { label: 'Number badge', doc: 'A number (No.1, 02) inside a star / jagged / round badge, optionally followed by a shop-name or title plate; rankings, lists, section intros (which shop, which tip).' },
  'common.tag': { label: 'Pill tags', doc: 'A row of small pill tags (comma separated) popping in one after another; small key points under a title: certification, type, price, distance. look: label is a location + date label of joined blocks (dark ground with white text and an accent edge, highlighter-colored date) that wipes in from the left within one beat. look: tape is a paper-tape label: each tag handwritten on its own strip of cream paper tape with a highlighter stroke growing under the words, no circled in red pen at the left of the first strip (a shop or stop number), the strips landing with a little bounce (notebooks, planners, walking maps). look: pin is a pin label: a teardrop map pin drops onto x, y (its tip) with a label card above it (the first tag, the second a small line under it); check ticks the pin\'s head at that second (maps, places visited, sights). look: glass is frosted glass tags (brand films); stack puts them in a column, and check ticks each one in the accent colour that many seconds after it appears (a checklist, things done). look day is a planner date label: a torn paper slip at x, y with tape on its corner, the first tag in a big italic serif (Day 2, 07:30) underlined in pen, the second handwritten under it (the weather, a place), popping in with a turn (the day of a vlog, a timeline of a day, a travel diary).' },
  'common.burst': { label: 'Burst card', doc: 'One big word inside a jagged burst shape (pops in, slightly tilted); a sticker-like burst word such as "Let\'s go!" or "So tasty!". A 【word】 in brackets turns accent-colored; common.speedlines can be added behind it. mode: blast bursts the whole frame open: a white flash, rotating rays, a pulsing red vignette, a huge word with a double outline (off the charts, record broken, the big reveal); rays is the moment of a bite: a ring of thin rays shoots out from (x,y) and a big word ("Crunch!") springs back from large to size at (tx,ty), tilted (bite, knock, smash, juice squirt).' },
  'common.speedlines': { label: 'Speed lines', doc: 'Comic speed lines radiating outward from one point (growing longer, flickering slightly); put behind a burst card, or at a moment of surprise, a dash or a turn.' },
  'common.caption': { label: 'Caption (shared)', doc: 'One line of caption in ten styles: outline / plain text / box / bubble (cream ground with a thick black border, accent words in the main color) / ticket (printed on a small strip of receipt paper with a torn jagged edge, popping up from below) / crayon (ink text over a highlight band scribbled with crayon, picture-book and handmade look) / bar (a dark rounded bar with a thin accent2 strip down its left side, like a search snippet) / qa (a magazine interview subtitle: serif text flush left over a dark wash rising from below, name in a square badge at the left of the first line, for example Q or A; with speaker above 0 the badge is in the main color) / auto (a social app\'s automatic caption: white text on a dark rounded box, popping in from 0.88×) / big (a social app\'s big sticker words: handwriting in the highlight color with a thick black outline, 1.25× larger, popping in from 0.6×). y can pin the caption\'s lower edge at any height (for example the video window\'s lower edge); name + speaker shows who is speaking (with tint off the text does not change color, only the name tag does; role adds a small identity next to the name); fill with words fades the whole sentence in lightly first, then the words light up as they are spoken and do not dim again; align left aligns to the left; point puts the name in a small speaker-colored tag at the left of the caption with an arrow pointing at the speaker (split-screen conversations); a 【word】 gets the highlight color, a {word} is censored into symbols; avoids the bottom and side safe zones of short-video apps. Style strip prints the words in ink on strips of paper, one slightly tilted strip a line, and with words the word being said gets a highlighter stroke (a planner or diary vlog).' },
  'common.slam': { label: 'Slam text', doc: 'One line of huge text "slammed" onto the frame (zooms in with a bounce, a slight shake, tilted); a 【word】 turns accent-colored (hlScale enlarges it). stagger slams each line down in turn; a small line can go above or below (kicker / after); enter: press shrinks from large like ink bleeding, chars bounces up one character at a time; bar wipes an accent-colored bar open under the text, drift enlarges very slowly once settled (a beat card); kickerBg puts the small top line in a color block that slides in from the left, shade darkens the area behind the text; look led is glowing red text in a black LED sign (a frozen confession). For key lines, exclamations, hooks and conclusions. look gold sets big italic serif words in a champagne-gold gradient with a dark soft glow and a warm flash as they land (a shout, a wish, a name).' },
  'common.censor': { label: 'Bleep sticker', doc: 'A censor sticker over the mouth (pops in, then sways left and right); used when a word can\'t be said, together with the common.beep bleep; move it with the item\'s transform.' },
  'common.stamp': { label: 'Stamp', doc: 'A boxed bold-text stamp "stamped" onto the frame (grows first, then drops, slightly tilted); shape: circle is a double-ring round stamp; verdicts such as verified, key point, recommended, done, NG; goes with common.thud. shape: card is a sticker-like stance card: a solid main-color card with thick white text (up to two lines, a 【word】 turns hl-colored), a black border with a hard shadow and a small tag at the side, dropping in from 1.35x; anchor sticks the card\'s top or bottom edge to y (one person\'s stance or a key line in a conversation or debate). shape: double is a verdict seal: a double-ruled rounded frame on a translucent paper ground with a soft shadow (verdict, rejected, case closed, certified); head adds a small widely spaced line above the word (VERDICT; on box, circle and double).' },
  'common.pen': { label: 'Hand-drawn marks', doc: 'Marks that appear as if drawn with a pen, stroke by stroke: circling, arrows, wavy underlines, plus a check, a cross, a heart, a star, a ring of small stars and hearts bursting (stars), a spiky halo (burst), surprise lines (rays), steam, a clock (its hands turn), a little house, a snowflake, a diamond, a question mark, a thumbs up; trace is a shape line across a cut: it traces a shape on the shot before the cut (from, points as fractions of the frame), carries over the cut at cut seconds, morphs onto the same shape in the next shot (to) within morph seconds and flashes as it locks on (match cuts, shape relays). style changes the pen: smooth clean lines (default), ballpoint, marker, crayon (fills are diagonal strokes with paper texture), pencil; boil makes the line re-wobble several times per second (a hand-drawn animation feel). Points out key spots, products and details in the frame; picture books, notebooks, tutorials.' },
  'common.sparkle': { label: 'Sparkle stars', doc: 'Four-pointed stars: bursting out from a point and scattering (burst), or scattered over the frame and twinkling (twinkle); celebration, surprise, emphasis, a premium feel.' },
  'common.emoji': { label: 'Emoji sticker', doc: 'One big emoji sticker that pops up and wobbles (sticker), or a rain of emoji falling from the top (rain, full frame; check does not count it as leaving the safe zone); float is a stream of hearts and emoji rising from x, y and swaying (a live stream\'s or social app\'s reactions, rate a second); tap is a double-tap\'s big heart popping at x, y with a ring of small hearts bursting out, then floating up and fading; in float and tap, ♥ is drawn as a pink heart; emotion, punchlines, celebration, foodie vibes, likes.' },
  'common.header': { label: 'Chapter label', doc: 'A chapter label at the top of the frame: a numbered color block plus a title (01 Intro, Step 2...); shows where you are in tutorials, lists and section intros. look kicker is a heading that stays up for a whole section: a main-color dot with small gray text above (the show name), and a bold title line below wiping open from the left, a 【word】 turning main-colored (what this film asks: interviews, podcasts, reviews).' },
  'common.glitch': { label: 'Glitch', doc: 'Several inverted horizontal bands are torn out of the frame and flicker in bursts; transitions, scares, a techy feel, the "something went wrong" moment (laid over the video; not a true RGB split).' },
  'common.progress': { label: 'Progress bar', doc: 'A progress bar along the top or bottom of the safe zone, a row of chapter dots, or a row of chapter tabs (icon + chapter name, finished ones ticked, the current one lights up and bounces), or pencil: a handwritten title with a red line on the left, and "Step 3/8" with a row of hand-drawn circles on the right (the current one filled red, finished ones ticked), or timeline: a thin line through evenly spaced dates (labels), a glowing dot sliding from stop from to stop step, the big date and the place (place) written under the line; step -1 draws the whole line out and writes "first day — last day" (the ending). Shows how far the film has got; common in hook shorts, tutorials, recipes and travel diaries.' },
  'common.meter': { label: 'Value meter', doc: 'A big number that jumps over time to each value (depth, altitude, temperature, a count, a rank…), with the current stage name and a ruler under it; in films whose spine is "more and more…", it makes the progress visible. look band is a year ruler: a dark band across the top, the number flush left with a smaller unit, a ruler from min to max with numbered ticks and a marker sliding along it, flags planted at values by pins (accent in the main color, hl in the highlight color, dashed a hollow flag on a dashed pole), and when the number reaches a flag its label appears beside it (years, history, eras). look ruler is an upright ruler at the right edge (height, altitude, ranks): every value reached leaves an arrow with its number, the newest one big in the main color, and a pin at the same value adds its label. A number in the third part of a stop is that stop\'s own count time (shared with ambient).' },
  'common.scoreboard': { label: 'Score ticket', doc: 'A ticket card at the top: a title row plus several cells (icon, name, value), one state per section; the cell that changes bounces and can carry a small note; records, catches, collection progress, rating cards (taste ★★★★).' },
  'common.receipt': { label: 'Receipt', doc: 'A thermal receipt: each line "second|icon|name|amount|tone" prints when its time comes (the paper grows downward, older lines scroll up), then a total prints last (【word】 turns red); tone bar is a white-on-black shop-name strip. Spending, travel expenses, unboxings, "what it cost vs what it got".' },
  'common.tripclock': { label: 'Trip clock', doc: 'The local time at the top of the frame (running forward with the shooting time), how long since arrival, and a route lighting up stop by stop; travel, one-day itineraries, films that follow the clock.' },
  'common.route': { label: 'Hand-drawn route map', doc: 'A hand-drawn route map on a beige paper card: a row of big-number promises at the top (number|caption), pencil streets below, and a red dashed line drawn from the start (a big clock or emoji) lighting up stop by stop, the last few stops can get question marks; shop hunts, one-day tours, walking routes, series teasers. look page is a whole-page notebook route map (fd-map): the places sit in a loop (or where pts puts them), the whole way is pencilled in faintly, a blue ballpoint dashed line is drawn leg by leg with the pen riding its tip, the walking time is written in red beside each leg (legs) with a wavy underline, each place turns into a doodle (icons: bowl / bun / box / jar / tofu / cup / station / train / house / star or an emoji) and a red tick as it is reached, its name hand-written on a highlighter swipe; the camera moves by cams "seconds|mode" between full (the whole map), walk (the map up top, room for the footage below), stop (shrunk to a scrap of paper in the corner, the current place pulsing), end and near (close in, following the current place); loop draws the way back to the start, flash makes every tick pop in turn; put it over common.paper look grid.' },
  'common.card': { label: 'Index card', doc: 'The top card of a stack of index cards: the upper half is a picture window (it can hold any block, such as the project\'s own illustration fx, or one big emoji), the lower half on ruled lines holds the step number, title, quantity (highlighter) and a small tip; turn the page to change step, cards can be dealt in and slide out at the end; recipes, tutorial steps, lists.' },
  'common.countdown': { label: 'Countdown', doc: 'A big number counting down from from to to (split evenly over the item), bouncing on every tick with a ring around it running out; the last tick can be replaced by a word (GO!); quizzes, challenges, guessing games, ranking reveals.' },
  'common.list': { label: 'List card', doc: 'A card with a title and several items appearing line by line; check (a ✓ tick), pros (+ pro / − con, an item starting with - counts as a con), number (1. 2. 3.); reviews, tutorials, three key points, myth-busting. look: stack has no card: big text slams in one line per beat, numbered color blocks, the newest line in highlighter color (keeps each photo\'s name during a burst of photos).' },
  'common.rating': { label: 'Rating card', doc: 'A rating card: several rows of "item:score" (stars can be half, or bars), the scores growing row by row, with an optional big total; food, unboxing, film and TV reviews.' },
  'common.info': { label: 'Info card', doc: 'A theme-styled info card: a title row plus several rows of "icon text" (📍 address, 🕐 opening hours, 💰 price, 🚇 transit...), sliding up from the bottom safe zone (or down from the top); travel, food, outfits, shop intros.' },
  'common.polaroid': { label: 'Freeze-frame Polaroid', doc: 'Freezes one moment of the footage into a Polaroid: a white flash first, then the photo drops in at an angle with one handwritten line below; highlights, travel, best moments (c.polaroid automatically takes source and time from the clip that is playing, and adds a shutter sound).' },
  'common.mystery': { label: 'Question-mark suspense', doc: 'A suspense cover: the edges of the frame darken, a main-color round seal with a question mark spins in at the center, one line above ("The 5th shop is...") and an optional hint below, with text on two taped-on paper-tape strips scrolling slowly; teasers that hold back the answer for the original film.' },
  'common.outro': { label: 'End funnel', doc: 'An end card that leads viewers on: paper-colored ground, several lines of big text stamped down one by one on the beat (【word】 goes into a small main-color tag), a row of numbered dots below (the last few with question marks), and a hand-drawn arrow drawn toward the link and bouncing on the beats; pointing to the original film, the profile, comments, the next episode. look credits is the closing thank-you list of a birthday, wedding or graduation: the lines fade up one a beat (*lines in stars* italic in the highlight color, _lines in underscores_ small and letter-spaced, the rest bold names) over a soft dark veil (cover sets how dark), y is the list centre; the opening name title is common.headline look name.' },
  'common.film': { label: 'Film texture', doc: 'Grain plus a vignette over the whole frame (one block); laid on the top layer when you want a film, nostalgic, textured feel; look vhs is a home video tape: fixed scanlines, a warm cast, lifted blacks and a vignette, and at the stretches tracking \"second:length:strength\" gives, a tracking-noise band slides down the frame (changing tapes, memories, old video tapes, DV; goes with common.whirr).' },
  'common.tone': { label: 'Color tone', doc: 'Color grading for the whole film: a soft-light layer over the video with colored light in the middle and darkened edges; warm by default (street food, sunsets, nostalgia), blue makes it cool; often used with common.film.' },
  'common.paper': { label: 'Paper desktop', doc: 'A paper ground for the whole film (kraft paper by default: fibers, specks, vignette), with an optional slightly tilted ruled index card (red top line, blue rules, washi tape), small pencil doodles and one italic signature line. look: book is a picture-book page (paper color paper, mottled paper grain, spine shadow and stitching at the left, page thickness at the right, vignette, a crayon meadow strip at the bottom); grid is a grid notebook (cell squares, a red margin line, binding coils along the top, vignette); print is magazine stock (smooth off-white with fine specks, faint fibres and a warm vignette, the paper of common.magazine); static, placed under the video; planners, recipes, handwritten tutorials, picture books, notebooks; goes with common.notecard (with card: false it writes on this card).' },
  'common.notecard': { label: 'Handwritten index card', doc: 'A ruled index card whose content is handwritten stroke by stroke: step (a red-pen circled number, a title, one or two lines of explanation, "label|content" fields), list (check boxes ticked item by item), title (a big dish name with a red underline, subtitle, foreign name), done ("Done!" plus a hand-drawn heart); recipes, tutorials, planner style; with card off it writes on the card drawn by common.paper. In list, tick makes a to-do list being ticked off: the list is already written, the card slides in from the left, the items before item tick are ticked and highlighted, item tick is ticked now with a highlighter stroke, and the card slides out again.' },
  'common.handwrite': { label: 'Handwriting', doc: 'Handwriting written stroke by stroke, each sentence with its own time: "second-second|sentence" gives handwritten captions written out character by character on the narration\'s timing (replace: one sentence at a time), accumulating line by line like writing a letter (stack), or a small note stuck on a photo (paper: note, with one line of small text); words listed in red are written in red pen and get an underline drawn beneath them when reached; postcards, diaries, planners, recipes.' },
  'common.gauge': { label: 'Gauge meter', doc: 'A half-circle speedometer: color zones (start:name) along the scale band, a spring needle, an LED digit readout and the current zone name, with a halo gradually turning into devil horns; each hit "second:points" makes the needle bounce; it can jitter at the start, sweep once on boot, flash a red alarm and finally max out (the needle slams to the end, the glass cracks); guilt index, spiciness, crush index, heat.' },
  'common.hangtag': { label: 'Points hang tag', doc: 'An evidence-tag style stamp stamped across the frame at an angle: a big "+points", a name, small original text and a one-line quip; then the "+points" flies to a chosen point (for example common.gauge) and bursts in a ring there; scoring, prices, calories, offences, collecting.' },
  'common.strike': { label: 'Strike-through rewrite', doc: 'A soft thin line of text floats up first (with a small heading line above), then at second at it is struck out with two red marker strokes and a big red-ground word stamp is put underneath; "it was A, actually B", expectation vs reality, myth-busting, reversals.' },
  'common.timelapse': { label: 'Fast-forward clock', doc: 'Time fast-forwarding: the frame darkens, the clock hands spin wildly, the hours below count up ("Chilled 2.3 hours"), and "▶▶ fast forward" flashes at the top; chilling, baking, fermenting, waiting, a jump cut across a night.' },
  'common.routeboard': { label: 'Route board', doc: 'A dark route board at the top: a mini map with real latitude and longitude (city dots, the walked line lighting up), the current stop flashing, the stop count 01/03 flipping like cards, and the date; stops "second|city|date" decides which stop lights up at each moment (- en route, all everything); hangs over a whole multi-city travel quick-cut.' },
  'common.mapjump': { label: 'Full-screen route jump', doc: 'The whole frame becomes a beige paper route map (real latitude and longitude, graticule lines and degrees) for a beat or two: leg draws a red arc from the previous stop to the next, the dot landing on the beat; all draws the whole route, each stop stamped in turn; a big title above and the date below; changing cities in a travel quick-cut, a full-trip recap.' },
  'common.ticket': { label: 'Arrival ticket', doc: 'A cream-colored ticket slams in below (red ticket head + No.01/03, a big city name, Latin text, a date stub at the right, perforation line), and at second stampAt a red double-ring "Arrived" stamp lands on it; each stop in a travel quick-cut, itineraries, tickets, boarding.' },
  'common.snap': { label: 'Photo flash-in', doc: 'When a photo comes in, a white light flashes, a white photo frame closes in from outside the frame, and an orange glowing camera date stamp sits in a corner (\'22 5 26); bursts of photos, memories, a film-camera feel.' },
  'common.stations': { label: 'Station stamps ending', doc: 'The last beat of an ending: the lower part of the frame darkens, a red line strings every stop\'s stamp together (a numbered red round stamp, a big station name, Latin text) which are stamped down together, then the date floats up; travel quick-cuts, series recaps, itinerary summaries.' },
  'common.postcard': { label: 'Postcard', doc: 'One stop of a postcard travelogue: a stack of postcards on a wooden table, a new one slides in (or flips over) and lands on top, a corner stamp (that stop\'s picture) and a postmark (place name + date) come down, and the narration is handwritten on the card character by character; when the card has settled the photo window is a transparent hole and the main-track clip (frame = postcardWindow) plays through it, while the window shows a still image when the card moves; the last card can flip to the back to write on and everything can be spread out; simple parameters give one card, card / pile / spread give the whole set.' },
  'common.postmark': { label: 'Postmark', doc: 'A postmark "stamped" onto the frame: a double ring, a place name on the upper arc, the local-language place name on the lower arc, the date in the middle, five wavy lines at the right, uneven ink, optionally with a perforated stamp (the picture is one moment of the footage; if none is given it is a drawn sunset sea); travel, sending letters, "been here", date stamps.' },
  'common.frame': { label: 'Physical frame', doc: 'A moving physical frame with the video playing inside it: a Polaroid, a wooden picture frame, an old TV or a card, dropping or sliding in, able to flip to the back to write on, able to leave; while moving the window shows a still image of the footage, and once settled the window becomes a hole through which the main-track clip (frame = frameWindow(params)) plays; memories, showcasing work, playback on an old TV, a person in a picture frame.' },
  'common.dotmatrix': { label: 'Dot-matrix text', doc: 'Dot-matrix text: any text (Chinese too) is shrunk to a dot matrix and drawn back dot by dot; look led is a black-ground marquee sign (lit dots glow, unlit dots form a grid), print is ink dots on thermal paper; mode still is static, marquee scrolls from right to left, type types out character by character; signs, marquees, LED boards, receipts, queue displays.' },
  'common.digits': { label: 'Digit display', doc: 'A digit display: style vfd is the green dot-matrix subtotal of a cash register ("second|+40": the number jumps up, a yellow "+40" flashes out, blinking at the total), led is a red seven-segment queue number ("second|02": the number flashes three times when it changes, with a vertical small plate beside it reading Now serving / Next); add title to make it a signboard (shop name and small text at the left, the display at the right); spending, scoring, queue numbers, countdowns, floors.' },
  'common.printer': { label: 'Receipt printer', doc: 'A thermal receipt printer (at the bottom of the frame): each line "second|style|text|amount" is printed in dot-matrix type with the stepper motor feeding the paper in jerks, the paper growing upward and disappearing behind the clip (the video window); shop is a white-on-black shop-name strip and the print head shows worn streaks; the machine\'s VFD subtotal jumps up automatically and flashes "+40"; at the end a stamp lands, a red pen strikes out a line, and tearAt tears off the whole receipt and spreads it in the middle of the frame; food spending logs, eating and adding up as you go, shopping lists.' },
  'common.rolldoor': { label: 'Roll-down shutter', doc: 'A roll-down shutter: steel slats are pulled down from the top to cover a frame (usually the video window), and once fully down a paper sign (Closed today) pops onto it; dir up starts closed and rolls up open at the given time; closing time, endings, "to be continued"; goes with the common.rattle sound.' },
  'common.callout': { label: 'Circle callout', doc: 'Marks something in the frame and pulls a callout line out to a label: circle a hand-drawn circle, cross an X, ban a prohibition icon (a circle with a slash, with a phone or any emoji inside), burst juice-squirt rays; the mark is drawn first, the line pulled out, the label pops up and stays inside the safe zone automatically; points out ingredients, methods, key points like "no phone orders".' },
  'common.slip': { label: 'Number slip', doc: 'A cream number slip: mode stub is a red number stub at the left (reason 01) + a dashed tear line, with a title and small text at the right, printed out from the left (which reason, a key line); mode board is an end number slip: big text, a dashed line, a numbered recap (items) popping in line by line, one line of small text at the bottom, with the background darkened; famous queue shops, three reasons, recap summaries.' },
  'common.quote': { label: 'Quote card', doc: 'A quote card: mode words is a dynamic quote: the video shrinks into a small window at the upper right (win), a big opening quotation mark and the speaker at the left, and below it lines of text jump out word by word on the speaking time (times; evenly spread if not given); the hardest-hitting line (hit, the last line by default) is enlarged and slammed down, the whole thing shakes once, a main-color light flashes and the earlier lines dim; pre puts some lines up first as dark teaser text, ghost lets the last line appear faintly first (an opening teaser); mode card is an opaque closing quote card: a big quotation mark, several lines floating up one by one (the hit line in the main color, earlier ones gray), a short line plus the source, and one line of small text at the bottom; quotes from podcasts, interviews and talks.' },
  'common.wipe': { label: 'Diagonal color-band transition', doc: 'A transition: a diagonally cut color band sweeps from left to right (dir can reverse it), covers the whole frame at the exact middle moment of the item and has a thin line on its leading edge; put the cut point (a layout switch, a scene change) at the exact middle of the item, and place it on the top layer (layer: top); goes with common.whoosh. mode hand is a hand over the lens: a dark, soft-edged palm silhouette with a motion trail slaps up from the lower right, covers the lens completely at the middle of the item, then slides away to the lower left (scene changes, turning away, not wanting to be filmed). mode curl is a page turn: the item starts at the cut with the old page covering the frame — a sheet in color, or the still of the outgoing shot (source / t / crop, in win or the whole frame) with a block held at artAt drawn over it (art / artParams, e.g. a common.magazine page, whose video window then holds the still) — and it curls away along angle: the fold sweeps across, the lifted part is the mirrored back (back color, a sheen by the fold, the print showing through faintly) casting a shadow, with a strip of shadow on the new page by the fold; rev plays it backwards (a page laid down, a magazine closing); magazine page turns, notebook pages, chapter changes; goes with common.whoosh.' },
  'common.duo': { label: 'Two-person split conversation', doc: 'A split-screen frame for two people (top and bottom with dir v, or left and right with h): a small color-block tag + topic at the head, a caption band between the two panes (below them when side by side), and a name plate at a corner of each pane; segs "start-end|a/b/ab" says who is speaking: the speaking pane lights up (an outline and inner glow in the speaker\'s color, a filled name plate, a jumping volume bar) while the other pane goes gray and dim; the two people\'s clips are put into the two panes with frame set to duoWindow(\'a\'|\'b\', the same parameters); two-person interviews, podcasts, debates, he said she said; goes with common.versus and caption\'s point.' },
  'common.versus': { label: 'Versus card', doc: 'A face-off card for two sides (goes with common.duo): mode title is an opener: a big word slams into each of the top and bottom panes (He said / She said), a VS diamond spins in on the caption band in the middle and the names sit at the sides; round is a full-frame round card: the two sides\' colors slide in from both edges and collide diagonally, ROUND 1 pops out, the question floats up (【word】 turns yellow) and finally is pulled away upward; table is a closing comparison table: "a vs b", two columns of names, one question per row (question|what a said|what b said|a tag|b tag, \\n for a line break) sliding in row by row, ending with a last question to the audience; two-person interviews, debates, comparing two methods.' },
  'common.chart': { label: 'Data chart', doc: 'A data chart card; kind changes the chart: bars bars grow out with numbers jumping up (dir h horizontal / v vertical bars; compare ratio shows a "× 6.7" multiple, gap shows a gap bracket; base a dashed baseline; stat one line of a big number jumping up), pie a pie painted slice by slice (note hangs a label below), people a row of little figures flipping one by one, the first k colored and circled (4 out of 10 people), rank a ranking list with one row lit and tagged "No. 12", balance a scale (weights drop into the two pans and it tips toward the heavier side), table a comparison table (lines drawn, cells floating up along the diagonal), line one or two curves drawn over time (playhead, markers on the curve, baseline); data is one entry per line "name|value|displayed text", hl which entry lights up (max, min or the nth), mark circle circles it, title the title, source the data source, time at is relative to the item start; look clean is simple (theme colors), hand is hand-drawn (pen picks marker / crayon / pencil / ballpoint, boil wobbles), woodcut is woodcut hatching on parchment; data, statistics, comparison, rankings, proportions, trends.' },
  'common.touch': { label: 'Touch dots', doc: 'The \"show touches\" dots of a screen recording: touches has one gesture per line, \"second|tap|x,y\" a tap, \"second-second|drag|x,y>x,y\" a drag (any number of points), \"second-second|pinch|x,y|0.4>0.15\" a two-finger pinch (the distance in short sides; growing means zooming in), \"second-second|press|x,y\" a long press; positions are fractions of the frame; a ripple rings out where the finger lands (ripple); look dot is the phone system\'s translucent gray dot, glow a glowing white fingertip; drawn above every other item; screen recordings of using a phone, app tutorials, photo albums, chats, searches.' },
  'common.headline': { label: 'Serif title card', doc: 'A documentary-style title card: a big serif headline (several lines allowed) with a line of small text, two thin rules growing out from the middle above and below, the whole card rising in and fading out at the end; bg band is a dark band behind the text, black turns the whole frame black (a serious card, chapters, years, places), none only the text and its shadow; type types the letters in one by one; chapter openings in history, documentary, essay and travel films. look name is the name title of a birthday, wedding or graduation: a big italic serif name (text) rising in letter by letter with one shimmer of light, a gold rule drawing out from a dot under it and a letter-spaced line (sub, for example SWEET SIXTEEN); the closing thank-you credits are common.outro look credits.' },
  'common.mapcam': { label: "Map camera", doc: "A camera that pans and zooms over a map photo from assets map (source = the map's source id; its longitude, latitude and zoom are kept with the download, older maps take at + zoom): cam keyframes \"seconds|place|zoom\" (empty = a slow push-in), layers stacks maps of one place at other zooms (each fades in once it covers the frame: from space down to the street), routes drawn leg by leg (an arrow, a dot or an emoji at the head), pins dropping in with names, rings, areas outlined, sea names and notes, big titles, a closing pin with a call to action; open / close grow it out of a small round map in a corner and shrink it back, mode mini is that corner map with the stop beside it; places name everything (name|Latin|lon|lat); with no map photo the world's coastline stands in. From the globe to a country use common.worldmap, then cut to mapcam (zoom ≈ log2(2π·cos lat·10^log10R / 256))." },
  'common.worldmap': { label: "Globe map", doc: "A hand-drawn world map: camera keyframes \"seconds|place|log10 radius|rotation\" fly from a globe in space (sphere, glow, graticule) down to a country, where the globe fades into a flat sea chart with rippled coasts; pins with name cards, routes as flight arcs (arc) or drawn along the places (line) with an emoji at the head (✈️ 🛵 ⛵), regions you give as a polygon or a box filled in the accent colour (on land only; there is no border data, so the shape is your points, not a real border), sea and land names, big titles; iris opens it as a circle from a point, card turns it into a small tilted map card. The coastline is Natural Earth 1:110m (enough for a country); closer than that cut to common.mapcam on a map photo. Opening locators, trips across countries, flight routes." },
  'common.notify': { label: "Notification stack", doc: "A phone's stack of notifications: items has one per line, \"seconds(-off seconds)|icon|app|title|body|key=value…\"; each comes in at its time (the newest on top, older ones pushed down; grow up is a chat, the newest at the bottom), cards past `full` pile up under the last one, \"s-s\" slides it off to the right at the second time; \"/\" breaks the body, 【word】 highlights; sub= a gloss in a second language, when= the time, tone= plain / light / dark / accent (accent: a big rounded card in the theme paper colour), lock hides the preview (a dim body and a padlock), chip= button words with chipAt= / press= unfolds a button and presses it; icons are built-in generic glyphs (bell work group cal mail phone msg mic play moon camera torch lock heart star pin bag music news plane gift sun clock user check alert app image search share trash info) or an emoji; covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device); goes over common.lockscreen (y 0.43); sounds: common.buzz (vibration), common.recv (message), common.hush (muted), common.send (swiped off / sent)." },
  'common.lockscreen': { label: "Phone lock screen", doc: "A phone's lock screen over the footage (the footage is the wallpaper): status bar (time / carrier / signal / wifi / battery), a mode pill (mode, one per line \"seconds|words|plain/calm/accent|icon\"), the date, a big clock (clock \"seconds|time\", changed digits flip up), a title line (title \"seconds|words\") with count dots (count \"seconds|n\", of = how many), a live-activity bar (live \"s-s\": the clock folds away and the bar takes the top; liveLabel goes before the count), the dock (two round buttons, the unlock hint \"seconds|words|up\" — up bounces with an arrow — and the home bar; band adds a solid dark strip that hides what is under it); covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device; wall gives it a wallpaper); notifications go on top with common.notify (y 0.43); sounds: common.buzz (vibration), common.recv (notification), common.hush (muted, mode change), common.tick (the clock flipping)." },
  'common.reels': { label: "Short-video frame", doc: "A short-video / story app's frame over the footage (a generic app, not any real one): mode feed runs the whole film — segment bars at the top (segs \"s-s\" separated by commas or lines; the slow one crawls and only finishes at the end; hook \"s-s|segment\" is a cold open that plays a later segment first and rewinds in its last 0.5 s with a rewind badge), the avatar with the account (handle) and a place, a title sticker (title, handwriting) with the segment chip (count), the heart / comment / share / save buttons at the right with their counts (likes, comments, shares: \"seconds|number\" one per line, eased between; counts writes them zh / ja in ten thousands (1.2 and the Chinese or Japanese sign for 10,000), en 1.2K, plain 12,345; taps are double-tap times: the heart pops and turns red; saveAt fills the bookmark), the account with a follow button (follow), the caption (caption + more), the music marquee (music) and the nav bar (nav); mode end goes over feed at the end: a pinned comment pops in (q, qName, pinLabel), the author's reply (reply, ███ becomes black bars; replyName empty = handle, authorLabel the author tag), a saved toast (toast, at saveAt), the share sheet (sheetTitle) slides up (sheetAt) and its big button (btn) is pressed at tapAt (the finger: common.touch); covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device: give common.comments and common.story the same value to stack on one phone); captions with common.caption auto / big, floating hearts with common.emoji float, the double-tap heart with tap, the comment stream with common.comments, story stickers with common.story; sounds: common.rewind (the cold open rewinding), common.pop (double tap, buttons), common.recv (a comment), common.send (share)." },
  'common.comments': { label: "Comment stream", doc: "A live stream of comments over any footage: items has one per line, \"seconds|name|comment|key=value\"; each comes up from the bottom at its time (avatar, name and the words on a dark bubble, wrapped on two lines when long), pushes the older ones up, stays hold seconds and fades; the ones pushed above top fade too; color= the avatar colour (by line when absent), avatar= an emoji or letter on the avatar (the name's first letter when absent); x and w are the left edge and the widest a row gets, bottom the newest one's foot, top where they fade (-1 auto: on 9:16 the safe area's foot, clear of common.reels' buttons); uses the whole 9:16 frame, on 16:9 / 1:1 it sits on the same phone as common.reels (device; none: no phone, the whole frame); sound: common.recv (one for each)." },
  'common.story': { label: "Story sticker", doc: "A story's interactive sticker (pops in, tilted by rot, shrinks away in the last 0.2 s): kind poll — a question (text) with two to four answers (options separated by |), the vote comes in at at and each bar fills to its result (votes, e.g. 62,38, the percentages counting up), a tick on pick; slider — a track under the question, the emoji slides to value (0–1) between at and end; timer — a dark sticker whose mm:ss runs from from seconds to to seconds between at and end (waiting or counting down; icon is a built-in glyph or an emoji); x, y are its centre (shares of the phone screen); uses the whole 9:16 frame, on 16:9 / 1:1 it sits on the same phone as common.reels (device); a location sticker is common.tag's label, a price common.hangtag, a text sticker common.tag / common.caption, a ring timer common.countdown; sounds: common.pop (appearing, the vote), common.tick (the timer)." },
  'common.album': { label: "Photo album", doc: "A phone's photo album as a screen recording (a generic app, not any real one: every word, tab, date, place and the status-bar time is a parameter; the icons are the built-in drawn set), five modes stacked on one phone: grid — photos one per line \"source|seconds|corner words|x,y\" (a project source id, a video at that second; - or empty = a painted stand-in; empty corner words = a video's length, - none; x,y the thumbnail's focus), \"# place|date|bubble words|layout\" starts a group (no place = the date alone; layout L big left and two small, R mirrored, 2 side by side, 1 full width, 3 rows of three, empty = by the count, threes alternating L / R; the rest in rows of three), scroll \"seconds|position|ease\" (position = a group from 0, fractions allowed; end = the bottom; 850px in px; ease out / inOut / linear / back), the date bubble at the right edge follows (bubble: the date and bubble words), hide \"s-s|photo\" blanks the tile flying open, the title (empty = the lit tab's name) and a top-right button, the tab bar (tabs \"icon|name\" comma separated, tab the lit one, -1 = the first on grid, the second on foryou), optional segmented chips (chips, chip); foryou — the memories page: title, section with a more link, one memory card (source / t / crop, empty = photo pick; cardTitle in handwriting, cardSub) that gives a little at tapAt, the next row's title (next) peeking in, fadeIn from the paper colour; zoom — a picture flying from zoomFrom to zoomTo (tile: tile pick, at the scroll position of the item start; full: the whole screen with crop as the main-track clip, so the real clip takes over; fit: the whole picture letterboxed; card: the memory card) within move seconds (ease), the black behind it following (full = black), fadeOut at the end; swipe — the viewer going left: this one (source or photo pick) leaves, the next (source2 or photo pick + 1) comes in from the right, fit / fit2 show a whole picture; viewer — the bars round a picture: back, date, when, the action word, the toolbar (tools: icons comma separated; heart pops and turns the heart colour at heartAt), show \"seconds|opacity\" keys (fade them once a clip plays); status bar time, battery; covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device; the main-track clip takes frame: screenFrame(width, height)); the finger is common.touch (albumTile(params, photo, seconds, width, height) gives where a tile is), handwritten notes common.handwrite, a white or black flash core.flash; sounds: common.tick (a tap), common.whoosh (opening, a fling, a swipe), common.thud (a pinch)." },
  'common.chat': { label: "Chat", doc: "A messaging app's conversation as a screen recording (a generic app, not any real one: every word is a parameter and the colours are its own), one item for the whole film: items one message per line \"seconds[-seconds]|who|content|key=value…\", who = me (right) / them (left, with the avatar; any other word = that group member's name) / sys (a grey system pill in the middle) / ch (a chapter pill); messages pop in at their time, the newest at the bottom, the conversation scrolling up; the kind goes after: text by default (\"/\" breaks a line, long lines wrap, the bubble's height follows its lines), typing (the other side's three dots, until their next message or \"s-s\"), photo, video (play=s-s cuts a rounded hole in the bubble while it plays: the main-track clip takes frame: chatWindow(params, message, width, height); mute icon, dur= length), album (pics=source@s,source@s,- several pictures, labels= a name on each), link (the content is the title, sub=, button=, badge= length, press= pressed), voice (dur=, play=s-s the wave fills, the content is its transcript), sticker (the content big, an emoji, no bubble); src= source id, t= the second (no source: a painted stand-in), t2= the poster after play, crop=x,y,zoom, ratio=4:5, w= width (share of the screen), tag= a label on a photo; my messages show the read mark readAfter seconds later (read changes the words; read=s per message, unread none), when= a small time; name= avatar= color= for group members; pin at the top (its title; with ch messages a row of chapter dots lights up, icon= a dot's icon, by default the emoji the chapter starts with); the header: name, status, avatar; the input bar types and deletes (inputs \"s-s|words|type/delete\"), hint when empty; panel the sticker panel under it (emojis, space separated; empty = none); wall \"seconds|#top|#bottom\" wallpaper colours eased between keys (noon to evening); covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device); the finger is common.touch (chatPoint(params, message, seconds, width, height) gives where), a big burst sticker common.burst, floating emoji common.emoji, subtitles common.caption; sounds: common.send, common.recv, common.typing, common.buzz (left on read), common.pop (a sticker)." },
  'common.search': { label: "Search page", doc: "A search engine's pages as a screen recording (a generic dark search page, not any real engine: no logo, no coloured letters; the tabs, related searches, searching…, did you mean, the featured snippet and full-version words are all parameters), by mode: home the start page over the main-track clip, blurred and darkened (the hint headline, query typed into the box, the autocomplete list sugg one row per line (\"prefix|completion\" or the whole row; the part that is the query is light, the rest bold), pick which row is tapped at pickAt and the box then holds it, out seconds sliding away); results the results page (the box types, erase deleting the old words first; tabs \"All, News…\" with the underline sliding from tabFrom to tab; title, titleSub, snip; the video window is a rounded hole, the main-track clip takes frame: searchWindow(params, width, height); a loading card until load; facts one card per line \"seconds|label|big|unit\" popping from the window's lower left; dym did you mean (dymAt, dymHi the letter marked, dymLead the words before it); big a big word over the window; related \"a, b; c\"; press the box lights up as search is pressed; view full = the clip fills the screen with the box, tabs and chips one per line \"seconds|word\" lighting up in turn floating at the top); ask questions opening (qs one per line \"s-s|question|hint\", hint redact = the answer hidden plus reveal; each opens into the video window and the list scrolls up a row as it closes); end the box typed again, a suggestion picked, at snipAt a featured snippet with the answer redacted (snipTitle, snipLead, snipNote), at cardAt a result card whose thumbnail is the video window (badge, title, dur, the play button pressed at press); times from the item's start; enter seconds pushing up from below; covers a 9:16 frame, on 16:9 / 1:1 a phone in the middle (device); the finger is common.touch (searchPoint(params, pick/bar/play, width, height) gives where), white flashes core.flash, subtitles common.caption, the ending common.outro; sounds: common.typing, common.tick (taps), common.pop (fact cards)." },
  'common.camcorder': { label: 'Camcorder viewfinder', doc: 'A home camcorder / DV viewfinder. mode osd sits over the footage: ● REC at the top left (blinking every second) / STBY / STOP / PLAY / PAUSE / FF / REW / PHOTO (status "seconds|state" one per line), corner marks (popping in at popAt) and a centre cross, the tape counter (counter "seconds|reading" sets it, then it runs with the state: 1× while recording, spin× in ff / rew, held otherwise; counterAt top puts it at the top right, bottom at the bottom left), TAPE number (tape "seconds|number", a tracking band at each change), battery (battery "seconds|bars", 0 blinks red), tape left (remain "seconds|minutes", under 1 minute blinks red), a date stamp (date "seconds[-seconds]|2004-08-14 10:30[|to date or rate]", laid out by dateFormat), a place typed in (place "seconds-seconds|words"), the W–T zoom bar (zoom "seconds-seconds|from|to"), TAPE END (end "seconds-seconds"); mode ff is fast-forward: snow → a blue screen with ▶▶ and the date rolling in big letters from `from` to `to` → snow; mode rew is the rewind: the stills of stills "source|seconds|x,y,zoom" flashing past backwards, faster and faster, torn, ◀◀ in the middle (painted stand-ins without footage); mode snow is snow only; every word (REC, TAPE, the months…) can be changed in words. Memories, weddings, home video, Y2K, travel DV; pair with common.film look vhs, common.beep kind rec / end and common.rewind' },
  'common.globe': { label: 'Dotted globe of origins', doc: 'A dotted 3D globe: land as glowing dots, places as dots with a breathing ring, the home brighter, arcs growing from place to place, the globe turning to bring a place to the front; an arc is drawn only on the near side and waits until the globe turns it into view, never climbing over the rim (origins, the home base, shipping, branches; places written as for common.worldmap).' },
  'common.wall': { label: 'Wall or ball of pictures', doc: 'The project pictures as rounded glass tiles in 3D: look wall is a gently curved wall the camera glides across, then pushes into one tile until it fills the frame width; look sphere is 90 tiles on a slowly turning ball whose far side fades; tall clips are cropped by cover, never squashed (we film a lot, the body of work).' },
  'common.logo': { label: '3D logo ending', doc: 'The ending of a brand film: the logo lands with a bounce in 3D and a light sweeps across, then it slides aside for the name rising letter by letter, and the tagline and the url come in from a blur; an SVG is extruded, a PNG or JPG becomes a plate cut to its shape, with no logo only the name; Latin letters are extruded, Chinese characters become thick cut-outs (bring the logo in first with npm run tellcut -- logo, which puts it in media/brand/).' },
  'common.dolly': { label: '3D frame push / pull', doc: 'A 3D frame push / pull: the clip on the face of a thick frame floating in space; dir in pushes the camera until the frame exactly fills the screen (its last frame is full frame, then the main-track clip carries on), dir out starts full frame and pulls back as the frame tilts away; a seamless switch between real footage and 3D, placed with c.dolly(clip id, { dir, len }) so the handoff lines up.' },
  'common.magazine': { label: 'Magazine page', doc: 'A magazine page the footage plays inside (the main-track clip with frame = magazineWindow(params) plays through its video window, a hole): magazine stock, a masthead (title) with the issue lines (issue / issueSub), the issue number and page (no / page) with a row of page squares, a double rule; layout feature is an inside page: still cells under the window pushing in slowly (cells "source|seconds|x,y,zoom", - is a painted stand-in), tags on the cells (tags "seconds|cell|EN|text"), a red kicker chip and a big white headline over the window\'s top left (settling smaller at settleAt), a pull quote over a cell (quote + quoteAt; slam drops it in hard, quoteEn a small English line, quoteBy who said it), the foot line; cover: a huge italic masthead, the window bleeding to the edges, a red banner headline sliding in (banner / bannerEn), cover lines on the cells below (lines), a barcode; list: the window on top, the kicker and headline on the paper and numbered rows coming in one by one (items "seconds|title|note"; contents, rankings); back: the footage full page under a dark wash, the masthead, a closing line (headline / deck) and a red play button (cta); tall frames put the cells under the window, square and wide frames beside it; interviews, travel issues, profiles, unboxings, rankings; turn pages with common.wipe mode curl.' },
  'common.casefile': { label: 'Case file', doc: 'A fact-check case file: a kraft folder on paper with a taped-down video window (the window is a hole; the main-track clip with frame = casefileWindow(params) plays through it), a header with who said it, the claim typed in and a row of evidence boxes stamped one by one by slots "seconds|label"; at strikeAt the claim is struck out with two red marker strokes and a double-ruled "rejected" stamp lands, at closeAt a flap folds down over the window and a "case closed" stamp lands; the header sits above the window on tall and square frames and beside it on wide ones; every word is a parameter. Fact checks, call-outs, a claim against the evidence, explainers, verdicts; pair with common.thud and common.whoosh' },
  'common.beep': { label: 'Bleep', doc: 'A 1 kHz TV bleep, its length matched to the word being censored; goes with the common.censor sticker; kind rec is a camcorder\'s two short high \"beep-beep\" when recording starts, end the three beeps of a tape running out or a battery going flat (these two ignore length and frequency; DV, home videos, with common.film\'s vhs).' },
  'common.whoosh': { label: 'Whoosh', doc: 'One sweeping wind-cut sound; transitions, elements flying in and out.' },
  'common.impact': { label: 'Impact', doc: 'One low-frequency heavy hit with a long tail; a slam word landing, a title appearing, a turning point.' },
  'common.shing': { label: 'Light sweep', doc: 'The bright sound of light sweeping across (a high hiss with a falling high tone); a logo landing, light across words, a reveal.' },
  'common.air': { label: 'Breath of air', doc: 'A breath of air that swells in and fades; a picture opening, a wall appearing, a breath between parts; bright opens it up.' },
  'common.riser': { label: 'Riser', doc: 'A rising sound getting higher and louder, ending on a high point; the build-up before a turn or a reveal.' },
  'common.pop': { label: 'Pop', doc: 'A short bubble "pop"; stickers, emoji, small elements popping up.' },
  'common.thud': { label: 'Thud', doc: 'One short low thud, like a stamp coming down; goes with common.stamp; paper: a rubber stamp on a paper card on a desk (an extra wood knock and paper sound), goes with common.postmark / common.postcard.' },
  'common.tick': { label: 'Tick', doc: 'One clean click; counting, progress, typing, text appearing character by character.' },
  'common.ding': { label: 'Ding', doc: 'One crisp ding; a right answer, a key point appearing, a flash of insight. A run of dings should climb step by step: the same pitch (the tonic), step 0, 1, 2... (scale: major / pentatonic).' },
  'common.error': { label: 'Error sound', doc: 'Two low "beep beep"s; a wrong answer, failure, NG.' },
  'common.shutter': { label: 'Shutter', doc: 'A camera shutter "click"; freeze frames, taking a photo, a Polaroid.' },
  'common.typing': { label: 'Typing', doc: 'A stretch of keyboard typing sound with adjustable length; text appearing one character at a time, searching, comments.' },
  'common.cash': { label: 'Cash register', doc: 'A cash register "ka-ching"; prices, saving money, earning money, spending big; coins adds the drawer popping open and coin sounds (totals, checkout).' },
  'common.deflate': { label: 'Deflate', doc: 'A sliding-down "pfff" deflating sound; doesn\'t count, disappointment, only a little movement, an awkward silence.' },
  'common.scratch': { label: 'Record scratch', doc: 'A record scratched to a stop, "skreee"; the mood turns suddenly, an interruption, a "wait a second" punchline.' },
  'common.powerup': { label: 'Power-up scan', doc: 'A gauge booting up: a servo motor winds up and back down, with a run of ticks; gauges, machines starting up, scanning.' },
  'common.alarm': { label: 'Alarm', doc: 'A short "beep, beep, beep" alarm (the number of beeps is adjustable); danger, about to max out, the last few seconds of a countdown.' },
  'common.explode': { label: 'Explosion + glass shatter', doc: 'A booming explosion with a low-frequency drop, then a burst of glass shards; off the charts, a mess-up, the big reveal; goes with common.burst\'s blast.' },
  'common.ffwd': { label: 'Fast-forward', doc: 'A tape fast-forward "whirr" climbing up; time fast-forwarding, skipping the wait; goes with common.timelapse.' },
  'common.page': { label: 'Page turn', doc: 'The rustle of a paper page turning; changing steps, changing cards, opening the next page; goes with common.notecard.' },
  'common.slide': { label: 'Card slide-in', doc: 'A card sliding across a stack of paper and finally settling gently; postcards, cards, photos sliding into the frame; goes with common.postcard / common.frame.' },
  'common.flip': { label: 'Card flip', doc: 'A card on a desk flipping over: two flaps of paper and air, then settling; flipping to the back, changing sides; goes with common.postcard / common.frame.' },
  'common.xylo': { label: 'Xylophone', doc: 'One short xylophone note; list ticks, items appearing one by one (the same pitch as the tonic, step 0, 1, 2... climbing step by step, scale: major / pentatonic; or change pitch directly to make a small melody).' },
  'common.print': { label: 'Print', doc: 'The whirr of a thermal receipt printer printing (print head plus stepper motor) with adjustable length; one sound per line printed; goes with common.printer.' },
  'common.clunk': { label: 'Paper-cutter clunk', doc: 'The "clunk" of a receipt printer\'s cutter or paper-feed latch; a new section, changing shops, a machine action.' },
  'common.tear': { label: 'Paper tear', doc: 'A sheet of paper torn off with a "rrrip"; tearing a receipt, tearing a calendar, tearing it up to start over; goes with common.printer\'s tearAt.' },
  'common.rattle': { label: 'Shutter rattle', doc: 'A roll-down shutter pulled down, a "clatter" ending in one final bang; closing time, wrapping up, the end; goes with common.rolldoor.' },
  'common.dingdong': { label: 'Ding-dong', doc: 'The queue machine\'s two "ding-dong" notes (high to low, A5 to F5 by default); changing numbers, next person, changing sections, arriving at a stop; goes with common.digits\'s led.' },
  'common.ringbell': { label: 'Ring bell', doc: 'A boxing ring bell "ding, ding" (the number of rings is adjustable): a hard strike with a long metallic tail; round start, a face-off, an opening VS, the end of a match; goes with common.versus\'s round card.' },
  'common.chime': { label: 'Sparkle chime', doc: 'A glittering chime climbing up (a glockenspiel arpeggio; the number of notes, starting note and gap are adjustable; chip: 8-bit square wave); sparkly, getting prettier, a reveal, magic, a rare item; goes with the common.sparkle visuals.' },
  'common.coin': { label: 'Coin', doc: 'An 8-bit game coin "ding-ling" rising (two square-wave notes, pitch adjustable); inserting a coin, scoring, getting an item, a gacha, collecting points.' },
  'common.fanfare': { label: 'Level-clear fanfare', doc: 'An 8-bit level-clear fanfare: four notes up, then one big chord (tonic adjustable); finishing, a full collection, winning, unlocking, the ending.' },
  'common.knock': { label: 'Wood knock', doc: 'A wood "knock knock" (count, gap and pitch adjustable; lower is like knocking on a door, higher like a wooden fish); knocking on a door, a reminder, counting one by one, a zen feel.' },
  'common.boing': { label: 'Spring boing', doc: 'A cartoon spring bounce "boing"; (pitch adjustable); jumping up, popping out, bouncy, a funny rebound.' },
  'common.footstep': { label: 'Footsteps', doc: 'A run of footsteps (count and gap adjustable, the left and right foot differ in pitch; soft: soft cartoon steps, wooden floor by default); walking into the frame, walking to the next room, sneaking closer.' },
  'common.flap': { label: 'Wing flap', doc: 'Wings flapping "flap flap flap" (count and gap adjustable); a bird flying away, flying into the frame, paper flying about.' },
  'common.whirr': { label: 'Tape winding', doc: 'The "whirr" motor sound of a video tape or cassette winding (length adjustable); changing tapes, rewinding, going back in time, old video tapes; goes with common.film.' },
  'common.scribble': { label: 'Pen scribble', doc: 'The rustle of a pen writing and drawing lines on paper (length and strokes per second adjustable; crayon: thicker and grainier); handwriting, drawing circles, ticking, doodling; goes with common.handwrite / common.pen (different from the common.scratch record scratch).' },
  'common.tape': { label: 'Tape tear', doc: 'A strip torn from a tape roll with a "rrrip" and then pressed on (with press off, just the tearing); sticking on labels, notes, photos; different from common.tear (a whole sheet of paper torn off).' },
  'common.clink': { label: 'Spoon on bowl', doc: 'A crisp "clink" of a spoon touching a porcelain bowl (glass: ice against a glass, three clinks); eating, stirring, drinking soup, iced drinks, a toast.' },
  'common.drip': { label: 'Water drip', doc: 'A water drop "plink" sliding upward (count, gap and pitch adjustable); dripping water, sweating, an idea popping up, slowly accumulating.' },
  'common.sizzle': { label: 'Sizzle', doc: 'Hot oil "sizzle" as food goes into the pan, with oil pops (length adjustable); pan-frying, deep-frying, stir-frying, into the pan, piping hot.' },
  'common.pour': { label: 'Pour', doc: 'The "splash" of water or a drink being poured (length adjustable); pouring tea, pouring soup, adding sauce, filling up.' },
  'common.cry': { label: 'Baby cry', doc: 'A cartoon baby crying "waaah" (count and pitch adjustable, soft and not harsh); babies, parenting, a meltdown, crying.' },
  'common.thunder': { label: 'Thunder', doc: 'Distant thunder: a soft crack, then a low rumble rolling away for about three seconds (seed gives another roll); a storm, the sky darkening, bad news, lightning; pair with common.ambient look sky and its lightning.' },
  'common.buzz': { label: 'Phone vibration', doc: 'A phone vibrating on a table, \"bzz — bzz\" (count adjustable); a call, a notification, a message coming in, being left on read, a jolt of feeling; goes with common.touch.' },
  'common.send': { label: 'Message sent', doc: 'The short upward \"whoop\" of a chat message being sent; sending a message, posting a comment, pressing send, publishing a post.' },
  'common.recv': { label: 'Message received', doc: 'Two soft notes going up when a message arrives (the second a fifth higher, pitch adjustable); a new message, the other side replying, a notification popping up; unlike common.dingdong (a queue machine\'s two notes going down).' },
  'common.hush': { label: 'Mute', doc: 'Two notes falling, \"doo-doo\": a notification turned off, muted, an alarm silenced, a call declined, not wanting to deal with it; unlike common.deflate (a deflating slide) and common.error (a wrong answer).' },
  'common.rewind': { label: 'Rewind', doc: 'A video tape rewinding: noise sweeping from bright to dull and a whine falling down (length adjustable); rewinding, going back in time, doing it again, a recap; the opposite of common.ffwd (fast-forward climbing up).' },
  'style:pluck': { label: 'Light pluck', doc: 'Bright plucked-string arpeggios, a small xylophone melody, soft shakers and claps; cheerful daily life, food, travel, unboxing.' },
  'style:lofi': { label: 'Lo-fi', doc: 'Lazy electric-piano seventh chords, a loose swung drum kit, a soft bass; studying, chatting, daily life, nights, memories.' },
  'style:cinematic': { label: 'Cinematic', doc: 'Slowly unfolding big synth pads, long bass notes, sparse bells, a swelling drum beat; landscapes, trailers, mood, documentaries.' },
  'style:tech': { label: 'Tech pulse', doc: 'A four-on-the-floor kick, a sixteenth-note pulsing bass, offbeat open hi-hats; tech, tutorials, data, AI, editing, hardcore.' },
  'style:playful': { label: 'Playful xylophone', doc: 'A bouncy xylophone melody, a low-high oom-pah accompaniment, shakers and claps; cute, funny, kids, pets, light daily life.' },
  'style:bout-bell': { label: 'Ring rounds', doc: 'A brisk quiz-show-style pulse (minor key, 100 bpm): the opening has a boxing ring bell plus an impact; the start of every section (a new round) has a whoosh + bell "ding ding" + a low-bass impact, the end of every section has a stamp thud and a held chord, and at the very end a snare roll leads into a bright closing chord; split-screen conversations, debates, he said she said, comparing two sides (the ring-bell sound effect is also available as common.ringbell).' },
  'style:chiptune': { label: '8-bit arcade', doc: '8-bit video-game music: a square-wave lead and fast arpeggios, a triangle-wave bass jumping in octaves, noise drums, a bright major key, upbeat (150 BPM); games, gacha, card draws, collecting, clearing levels, retro.' },
  'style:funk-minor': { label: 'Minor funk', doc: '96 BPM minor funk: a plucky synth bass (octave pops), boom-bap drums, 2/4 handclaps, swung hi-hats, offbeat muted clavinet, with the drums and bass dropping out for half a beat before each section; quotes, kinetic text, punch lines, comedy, a street feel (scratch, stamp and other sound effects are placed with c.sfx).' },
  'style:garden-folk': { label: 'Afternoon kitchen', doc: 'Gentle afternoon-kitchen folk: plucked arpeggios, a music-box melody, a warm pad, light shakers and brushed drums, no kick drum; handwritten recipes, baking, handmade crafts, slow-living vlogs.' },
  'style:guzheng-pop': { label: 'Guzheng light electronic', doc: 'Pentatonic guzheng plucks (with pressed-string slides) + yueqin arpeggios + a light electronic beat (96 BPM), going from sparse to full and then returning to the guzheng; Hakka and Taiwanese tradition, modern information explainers with an Eastern flavor, cultural introductions, local food.' },
  'style:hijaz-route': { label: 'Spice route', doc: 'A Middle East / Silk Road flavor: oud plucks in the Hijaz scale over a low drone (tonic + fifth), flute, frame-drum dum/tek and shakers (84 BPM), going from sparse to full by film length, in long films leaving only the drone and bells at the seventy-percent mark, and finally returning to the theme and ending on a big chord; explainers on history, maps, seafaring, spices, ancient civilizations and markets.' },
  'style:lullaby-box': { label: 'Night-light music box', doc: 'A gentle night-light music box (72 BPM, major key): a music-box melody, a warm pad, a soft bass, felt-piano arpeggios; the middle turns to a minor key with a low heartbeat, the later part adds a glockenspiel, and before the end there is space with only a single note; parenting, bedtime, babies, warm science explainers or memories.' },
  'style:market-groove': { label: 'Night market groove', doc: 'An urban pop groove on the royal-road progression: syncopated electric-piano chords, a bouncy bass, small wood-block and xylophone hooks; lively but clean street snacks, markets, shop visits.' },
  'style:mischief': { label: 'Sneaky pluck', doc: 'A sneaky plucked groove (D minor, 120 bpm): an opening accent, one gentle bar, a layered sneaking-a-bite groove growing thicker, a held breath with only a ticking heartbeat, stacked snares, a drum roll, a bang, and an ending on a bright open D chord; funny contrast, scoring, maxing out, shorts that get more and more exaggerated.' },
  'style:postcard-felt': { label: 'Postcard felt piano', doc: 'A slow felt piano: arpeggios in the left hand, a sparse little melody in the right, an occasional music-box note; gentle, nostalgic, like a letter to yourself, suited to slow-paced travelogues and memories.' },
  'style:queue-call': { label: 'Queue-call minor', doc: 'Light xylophone + plucked bass + shakers, with the queue machine\'s "ding-dong" at the start of each section and a low drum hit before the ending; snack shops, famous queue shops, introducing shop after shop, which reason number (the number-change ding-dong sound is also available as common.dingdong).' },
  'style:quote-drop': { label: 'Quote drop', doc: 'A quiet minor-key interview bed: a heartbeat bass, muted plucks, light hi-hats; a one-bar teaser at the start (bass drone + riser + deep impact), half a bar before the quote at about sixty percent where everything stops except the riser, a deep impact and a high bell on the first beat of the quote bar, then it turns major to finish; the strongest line of a podcast quote, interview or talk (place the quote on the first beat of the bar of quoteDropPlan(bars).hit).' },
  'style:rail-beat': { label: 'Station beat', doc: '120 BPM minor electronic beat: a half-speed opening hit, a four-on-the-floor kick, a kick pulled out and a riser when changing cities and then a hit on arrival, a replay section with sixteenth-note hi-hats and a pulsing lead, a snare push, and a hit after a break to end; sections are arranged automatically by bar count; beat-synced quick cuts, travel rhythm edits, multi-city trips.' },
  'style:receipt-hop': { label: 'Receipt hop', doc: 'A light cash-counter slice of life: offbeat plucked chords, a walking bass, shakers and light claps, a little xylophone tail, small cash-register-like ticks; food spending logs, lists, shopping.' },
  'style:steelpan-bossa': { label: 'Summer steelpan', doc: 'A cool summer light bossa (100 BPM, major key): steelpan, marimba arpeggios, Rhodes seventh chords (city-pop progression), a root-fifth bass, rim clicks, shakers; mostly just a thin rhythm so people can talk, with the melody opening up only for a short middle bit and the last section; ice cream, summer, the seaside, talkative food introductions.' },
  'style:walking-pizz': { label: 'City stroll', doc: 'A strolling feel (100 BPM, light swing): plucked string chords, a wood bass walking in quarter notes, brushed drums, small glockenspiel replies, a whistled melody; map routes, shopping, strolling, eating while walking, small city trips.' },
  'style:candle-glow': { label: 'Candle glow', doc: 'A warm celebration score (72 BPM, major): electric piano motif, string pad, celesta glints, a plucked groove; it follows the film through cues: low turns minor with only a low drone, bright blooms back to major, play bounces, wait holds before a surprise, shout falls silent for the cheer, party grooves gently, quiet leaves only a pad while the room sings, tender is piano alone; birthdays, weddings, graduations, farewells, surprise parties.' },
  'recipe:travel': { label: 'Narrated travel', doc: 'Scene-by-scene narration with footage: captions follow the narration, one place label per scene, a title and an end card, music ducked during narration; travel, city strolls, memories.', notes: [
    'Each scene\'s length is set by its narration (narration length + gap seconds between scenes), and the shots in a scene share that time by weight; the last scene gets 1.5 extra seconds.',
    'A shot never crosses into the next scene of the footage: when the wanted length runs past the scene from sits in, from is moved earlier; if the whole scene is too short it is used as is and a warning appears in the result (use another stretch of footage or add a shot).',
    'The title is about 2.4 seconds and the end card (end) 3.5 seconds, both counted in the film length.',
    'music can be a style name, or { style, bpm, key, seed, gain }; a newly written style goes in projects/<id>/score/.',
  ] },
  'recipe:hook': { label: 'Hook short', doc: 'A hook short cut from talking footage: a panel layout, an opening burst word, a number badge and tags for each segment, speech captions (highlighting, censoring, fixing wrong words), chapter dots, and a closing call to action; food, interviews, podcasts.', notes: [
    'The layout from top to bottom does not overlap: badge and tags (0.05–0.13 of the frame height) → panel (0.15–0.62 by default) → chapter dots (right below the panel) → captions (above the bottom interface zone).',
    'panel can be given { frame: [x, y, width, height] } to move the panel; the chapter dots stay stuck below it.',
    'A censor word must be one that is really spoken in that segment (judged by the transcript); words the transcript misheard are fixed in the captions with fix (without affecting the censor matching).',
    'cta is laid over the last 2.2 seconds of the last segment.',
    'Each segment defaults to tighten: true: pauses in speech longer than 0.6 seconds are shortened to 0.3 seconds, so a segment is shorter than len; to keep the pauses (for example waiting for a punchline) give tighten: false.',
    'captions can be given the sentences to keep (for example ["fresh", "tasty"]: only captions containing those words are kept).',
    'c.recipe returns the item ids made for each segment (segments[i].clip (the first piece after trimming pauses) / pieces (all) / badge / tags / captions / progress): afterwards fine-tune any of them with c.update(id, { params: { size: 5 } }) or { transform: { x, y, scale } } (badge, tags and chapter dots hang on each segment\'s clip, and start / end given are in seconds relative to that clip).',
  ] },
  'recipe:brand': { label: 'Brand film', doc: 'A company brand film: short hook lines over everyday shots, a photo wall with a number that counts up, the company\'s own 3D part, what they do (a dolly into the first shot, glass tags), proof numbers, who we are, and the 3D logo landing on the music\'s peak.', notes: [
    'Every time sits on a bar (cinematic at 80 BPM by default, a bar is 3 seconds): a bar per hook line, the last one 1.5; the wall 1.5; scene as many bars as it says; each beat 1.5; proof 2; we are 1 plus 0.5 for the dolly out; the logo 3 (it lands at the end of its first bar). About 60 seconds = 3 hook lines, 4 beats, 1–2 proofs.',
    'Footage rules (checked before anything is laid out; an error if not met): in the main cut (the shots of hook, beats and weAre) a source\'s same in-point is never used twice; a source at most twice, the two in-points at least 3 seconds apart; at least as many distinct sources as hook lines plus beats. If there are not enough, find more footage instead of repeating.',
    'The wall\'s tiles must be photos, and not used in the main cut: assets get takes several Pixabay photos at once (pixabay:image-…), 30–40 is best; the proof\'s turning ball uses these photos too.',
    'The first beat\'s shot.from must be at least half a bar (1.5 seconds at 80 BPM): the footage before it goes to the 3D frame the camera pushes into; leave half a bar after the weAre shot for the dolly out too.',
    'proof holds only numbers and facts from the user\'s own text (big for the number, for example "90+", label for the small text under it; a sentence with no number goes in line); none: an empty array, and the part is left out.',
    'scene is a 3D project block written for this company (fx.*, three: true), loaded first with c.fx(…); params are its own.',
    'style cinemascope adds 2.39 letterbox bars to a landscape film and keeps the words above the bottom bar; a vertical film has no bars.',
    'It returns the start and end seconds of each part (parts); fine-tune afterwards with c.update (for example a line\'s timing).',
  ] },
  'recipe:montage': { label: 'Music montage', doc: 'Shots cut on the beats of the music: a section every four shots, a white flash and whoosh at the start of each section, a title and big text cards, a film texture; weddings, travel memories, event records.', notes: [
    'Film length = the beats of all shots × seconds per beat (60 / bpm), plus the end card (end) of 8 beats.',
    'mood decides about how long each shot stays (gentle 3.5 seconds, steady 2.5, lively 1.6, urgent 1), rounded to whole beats; rhythm defaults to varied: every four shots alternate in lengths of about "1, ½, 1½, 1" times (a section\'s total length stays the same and still lands on the bar), so they are not all the same length (like a slideshow). When beats is given it defaults to even.',
    'A shot with hero: true stays for two base lengths (the longer one when it sits at a longer position), kept for the most important picture of the film; drop is the index of that shot, and the music leaves two beats of space when it starts (a pause at the emotional peak).',
    'Give a shot\'s sound in dB (for example -14) to keep its own sound (laughter, waves); without it there is only the music.',
    'Two adjacent shots should not be adjacent positions of the same footage (it looks like a jump cut), nor have the same subject and shot size in a row; the former is warned about on save.',
    'shot in cards is a shot\'s index, counted from 0 (the first shot is 0).',
    'title can be a string, or { text, size } (size is the font size, in % of the frame height, 9 by default; reduce it for a long title); write line breaks as \\n.',
    'A shot\'s beats can be set individually (for example 8 beats for the last one), overriding mood, rhythm and hero.',
  ] },
  'clip.shake': { label: 'Camera shake', doc: 'The clip that is playing at that time shakes and then slowly settles: slam words, impacts, punchlines. To make a hook recipe\'s opening shake, add shake: true to the hook.' },
  'clip.follow': { label: 'Sticker follows the mouth (or face)', doc: 'Any sticker can be attached to the mouth or face of the person in the clip and move with them; with several people add who: left / right / largest / center. Censoring: censorSpeech(…, { follow: true }).' },
  'clip.avoidBurned': { label: 'Avoid the original\'s burned-in captions', doc: 'When the original footage\'s burned-in captions (detected during analysis) fall in this stretch, it is automatically zoomed and cropped to push the captions out of the frame; if even 2.2x zoom cannot avoid them it is left as is with a warning.' },
};
